uses GraphWPF;

const
  max = 10;
  coef1 = 0.5;
  coef2 = 0.88;
  scalex = 0.0035;
  scaley = 0.0035;
  dx = 430;
  dy = 300;

begin
  Window.Title := 'Fractals: Mandelbrot Set';
  Window.SetSize(600,600);
  Window.CenterOnScreen;
  var m := Window.Width.Round;
  var n := Window.Height.Round;
  var a := new Color[m,n];
  for var ix:=0 to m-1 do
  for var iy:=0 to n-1 do
  begin
    var cx := scalex * (ix - dx);
    var cy := scaley * (iy - dy);
    var c := Cplx(cx,cy);
    var z := Cplx(0,0);
    var i := 1;
    while i<255 do
    begin
      z := z*z+c; 
      if z.Magnitude>max then break;
      i += 1;
    end;
    if i>=255 then a[ix,iy] := Colors.Red
      else a[ix,iy] := RGB(255,255-i,255-i);
  end;
  DrawPixels(0,0,a);
  Writeln('Calculation time = ',Milliseconds/1000,' s');
end.

